typedef unsigned long size_t;
typedef struct _IO_FILE FILE; extern FILE *stdout; int setbuf(FILE*,char*);
void *malloc(size_t); void free(void*);
int printf(const char*,...);
int main(void){
  setbuf(stdout,0);
  char *A=malloc(0x410),*B=malloc(0x410),*G=malloc(0x410);
  printf("A=%p size=0x%lx\n",(void*)A,((unsigned long*)A)[-1]);
  printf("B=%p size=0x%lx\n",(void*)B,((unsigned long*)B)[-1]);
  printf("G=%p size=0x%lx\n",(void*)G,((unsigned long*)G)[-1]);
  free(A); printf("free(A): A -> unsorted (size 0x%lx)\n",((unsigned long*)A)[-1]);
  free(B); printf("free(B): backward consolidation B+A -> size 0x%lx at %p\n",((unsigned long*)A)[-1],(void*)A);
  void *D=malloc(0x830);
  printf("malloc(0x830) -> %p (== A? %s) size now 0x%lx\n",D,D==A?"yes":"no",((unsigned long*)D)[-1]);
  return 0;
}
